      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          val coroutineScope = rememberCoroutineScope()
          var currentScreen by remember { mutableStateOf<Screen>(Screen.Register) }

          var patients by remember { mutableStateOf<List<PatientItem>>(emptyList()) }
          var isPatientsLoading by remember { mutableStateOf(true) }

          val visitsCache = remember { mutableStateMapOf<String, List<AncVisit>>() }
          var isVisitsLoading by remember { mutableStateOf(false) }

          var questionnaireJson by remember { mutableStateOf("") }

          fun loadPatients() {
            coroutineScope.launch {
              isPatientsLoading = true
              try {
                patients = repository.getPatients()
              } finally {
                isPatientsLoading = false
              }
            }
          }

          fun loadVisits(patientId: String) {
            coroutineScope.launch {
              isVisitsLoading = true
              try {
                val visits = repository.getVisitsForPatient(patientId)
                visitsCache[patientId] = visits
              } finally {
                isVisitsLoading = false
              }
            }
          }

          LaunchedEffect(Unit) {
            loadPatients()
            launch {
              questionnaireJson = repository.getQuestionnaireJson()
            }
          }

          when (val screen = currentScreen) {
            is Screen.Register -> {
              RegisterScreen(
                patients = patients,
                isLoading = isPatientsLoading,
                onRefresh = { loadPatients() },
                onPatientClick = { patient ->
                  currentScreen = Screen.PatientDetail(patient)
                  loadVisits(patient.id)
                }
              )
            }

            is Screen.PatientDetail -> {
              BackHandler {
                currentScreen = Screen.Register
              }

              val visits = visitsCache[screen.patient.id] ?: emptyList()
              PatientDetailScreen(
                patient = screen.patient,
                visits = visits,
                isLoading = isVisitsLoading,
                onRefresh = { loadVisits(screen.patient.id) },
                onBackClick = {
                  currentScreen = Screen.Register
                },
                onRecordVisitClick = {
                  currentScreen = Screen.RecordVisit(screen.patient)
                }
              )
            }

            is Screen.RecordVisit -> {
              BackHandler {
                currentScreen = Screen.PatientDetail(screen.patient)
              }

              RecordVisitScreen(
                patient = screen.patient,
                questionnaireJson = questionnaireJson,
                repository = repository,
                onVisitSaved = {
                  // Reload visits and return to Patient Detail screen
                  loadVisits(screen.patient.id)
                  currentScreen = Screen.PatientDetail(screen.patient)
                },
                onCancelClick = {
                  currentScreen = Screen.PatientDetail(screen.patient)
                }
              )
            }
          }
        }
      }
    }
  }
}

